//! Call targets for Rust from a rust-analyzer SCIP index; `rust_types` reads the
//! same index for trait targets and type references.
//!
//! SCIP records which symbol every name refers to but not whether a name is a
//! call, so the call sites come from the `syn` measurement and SCIP supplies
//! their targets. rust-analyzer runs with the build-script command replaced by
//! `cargo --version`: no `build.rs` runs, no proc-macro library is known, and
//! cargo stays offline without `RUSTC_WRAPPER`. Code generated by build scripts
//! or proc macros is therefore missing and its calls stay unresolved. It also
//! runs without `cfg(test)`: test-only code is not indexed (a quarter less
//! time on this repository) and its calls stay unresolved.
use std::collections::{BTreeMap, HashMap, HashSet};
use std::ffi::OsStr;
use std::path::Path;
use std::process::Command;
use std::sync::{Mutex, OnceLock};

use archguard_core::{CallAnalysis, CallClass, CallMethod, MethodCall};
use protobuf::Message;
use scip::types::{Index, PositionEncoding};
use sha2::{Digest, Sha256};

pub(crate) mod background;
mod disk;

const HINT: &str = "Install rust-analyzer (rustup component add rust-analyzer, or brew install rust-analyzer) or set ARCHGUARD_RUST_ANALYZER to its executable.";
/// SCIP `SymbolRole::Definition`.
const DEFINITION: i32 = 1;

/// A call expression in a measured body, located at its callee name.
pub(crate) struct CallSite {
    /// 1-based line and 0-based character column of the callee identifier.
    pub line: u32,
    pub column: u32,
    /// The callee as written: `Cart::new`, `shop::audit` or a method name.
    pub label: String,
    pub method_call: bool,
}

/// One parsed Rust source: walked path, graph-relative path and text.
pub(crate) struct Source {
    pub rel_path: String,
    pub stripped: String,
    pub text: String,
}

#[derive(Clone)]
pub(crate) struct ScipIndex {
    pub version: String,
    /// Document → (0-based line, start offset in the document's encoding) → symbol.
    occurrences: HashMap<String, BTreeMap<(u32, u32), String>>,
    /// Symbol → (document, 0-based line) of its definition inside the project.
    definitions: HashMap<String, (String, u32)>,
    encodings: HashMap<String, PositionEncoding>,
    /// Set for an index of an earlier state: what to report until the
    /// current one is there.
    pub pending: Option<String>,
}

type Cached = ([u8; 32], ScipIndex);
static CACHE: OnceLock<Mutex<Option<Cached>>> = OnceLock::new();

/// Identity of an index: rust-analyzer, root, sources and manifests.
fn fingerprint(root: &Path, executable: &OsStr, sources: &[Source]) -> [u8; 32] {
    let mut hash = Sha256::new();
    hash.update(executable.as_encoded_bytes());
    hash.update(root.to_string_lossy().as_bytes());
    for source in sources {
        hash.update(source.rel_path.as_bytes());
        hash.update(source.text.as_bytes());
    }
    for manifest in [
        "Cargo.toml",
        "Cargo.lock",
        "rust-toolchain",
        "rust-toolchain.toml",
    ] {
        hash.update(std::fs::read(root.join(manifest)).unwrap_or_default());
    }
    hash.finalize().into()
}

/// Source path → SHA-256 of its text.
fn document_hashes(sources: &[Source]) -> HashMap<String, [u8; 32]> {
    sources
        .iter()
        .map(|s| (s.rel_path.clone(), Sha256::digest(s.text.as_bytes()).into()))
        .collect()
}

/// The SCIP index of `root`, from cache while sources and manifests are
/// unchanged. With the background hook set (desktop) a missing index is
/// built on its own thread; meanwhile the index of an earlier state serves
/// the documents that did not change, or the call fails with a note.
#[tracing::instrument(skip_all)]
pub(crate) fn index(
    root: &Path,
    executable: &OsStr,
    sources: &[Source],
) -> Result<ScipIndex, String> {
    let fingerprint = fingerprint(root, executable, sources);
    let cache = CACHE.get_or_init(|| Mutex::new(None));
    let mut guard = cache.lock().unwrap_or_else(|e| e.into_inner());
    if let Some((old, index)) = &*guard
        && *old == fingerprint
    {
        return Ok(index.clone());
    }
    let dir = disk::cache_dir();
    let kept = dir.as_deref().and_then(|d| disk::load(d, root));
    if let Some(kept) = kept.as_ref().filter(|k| k.fingerprint == fingerprint)
        && let Ok(index) = parse(kept.version.clone(), &kept.bytes)
    {
        *guard = Some((fingerprint, index.clone()));
        return Ok(index);
    }
    drop(guard);
    let documents = document_hashes(sources);
    let (owned, executable) = (root.to_path_buf(), executable.to_os_string());
    let build = move || {
        let (version, bytes) = run(&owned, &executable)?;
        let index = parse(version.clone(), &bytes)?;
        if let Some(d) = &dir {
            let kept = disk::Kept {
                fingerprint,
                version,
                documents,
                bytes,
            };
            let _ = disk::store(d, &owned, &kept);
        }
        // Failures are not cached: a missing tool or a timeout may be transient.
        *cache.lock().unwrap_or_else(|e| e.into_inner()) = Some((fingerprint, index.clone()));
        Ok(index)
    };
    let Some(ready) = background::hook() else {
        return build();
    };
    let current = document_hashes(sources);
    let note = background::start(root, fingerprint, move || build().map(drop), ready);
    match kept.and_then(|k| earlier(k, &current)) {
        Some(mut index) => {
            index.pending = Some(note);
            Ok(index)
        }
        None => Err(note),
    }
}

/// An index of an earlier state, without the documents whose text changed
/// or that are gone: their positions and definitions may have moved.
fn earlier(kept: disk::Kept, current: &HashMap<String, [u8; 32]>) -> Option<ScipIndex> {
    let index = parse(kept.version, &kept.bytes).ok()?;
    Some(index.without(&changed(&kept.documents, current)))
}

/// Byte offsets where the lines of `text` start, for [`line_at`].
pub(crate) fn line_starts(text: &str) -> Vec<usize> {
    let ends = text.match_indices('\n').map(|(at, _)| at + 1);
    std::iter::once(0)
        .chain(ends.filter(|&start| start < text.len()))
        .filter(|_| !text.is_empty())
        .collect()
}

/// The 1-based `line` of `text`, as `text.lines().nth(line - 1)` gives it
/// ("" past the end), without scanning the text before it.
pub(crate) fn line_at<'a>(text: &'a str, starts: &[usize], line: u32) -> &'a str {
    let Some(&start) = (line as usize).checked_sub(1).and_then(|i| starts.get(i)) else {
        return "";
    };
    let end = starts.get(line as usize).copied().unwrap_or(text.len());
    let slice = &text[start..end];
    match slice.strip_suffix('\n') {
        Some(rest) => rest.strip_suffix('\r').unwrap_or(rest),
        None => slice,
    }
}

/// Documents whose text differs between two states, or that only one has.
fn changed(
    kept: &HashMap<String, [u8; 32]>,
    current: &HashMap<String, [u8; 32]>,
) -> HashSet<String> {
    let differs = |a: &HashMap<String, [u8; 32]>, b: &HashMap<String, [u8; 32]>| {
        a.iter()
            .filter(|(path, hash)| b.get(*path) != Some(*hash))
            .map(|(path, _)| path.clone())
            .collect::<Vec<_>>()
    };
    differs(kept, current)
        .into_iter()
        .chain(differs(current, kept))
        .collect()
}

/// Run on the user's default toolchain and its rustc: a `rust-toolchain.toml`
/// or `build.rustc` in the repository could name a program of its own.
/// Without rustup the environment stays as it is.
fn pin_toolchain(command: &mut Command) {
    let home = std::env::var_os("HOME")
        .map(std::path::PathBuf::from)
        .unwrap_or_default();
    let rustup = |args: &[&str]| {
        let out = Command::new("rustup")
            .args(args)
            .current_dir(&home)
            .output()
            .ok()?;
        let text = String::from_utf8(out.stdout).ok()?;
        out.status
            .success()
            .then(|| text.split_whitespace().next().map(str::to_owned))
            .flatten()
    };
    let Some(toolchain) = rustup(&["default"]) else {
        return;
    };
    command.env("RUSTUP_TOOLCHAIN", &toolchain);
    if let Some(rustc) = rustup(&["which", "rustc", "--toolchain", &toolchain]) {
        command
            .env("RUSTC", &rustc)
            .env("CARGO_BUILD_RUSTC", &rustc);
    }
}

/// The `--version` line of `executable`, run like the index itself: confined,
/// on the user's toolchain, in `scratch` and within the time budget.
fn version(root: &Path, executable: &OsStr, scratch: &Path) -> Result<String, String> {
    let mut command = crate::compiler_sandbox::command(executable, root, scratch);
    pin_toolchain(&mut command);
    command.arg("--version");
    let out =
        crate::go_calls::execute(&mut command, scratch, None, "rust-analyzer --version", HINT)?;
    Ok(String::from_utf8_lossy(&out).trim().to_string())
}

/// rust-analyzer's version and the raw SCIP index it wrote for `root`.
#[tracing::instrument(skip_all)]
fn run(root: &Path, executable: &OsStr) -> Result<(String, Vec<u8>), String> {
    let dir = tempfile::tempdir().map_err(|e| e.to_string())?;
    let version = version(root, executable, dir.path())?;
    let config = dir.path().join("rust-analyzer.json");
    std::fs::write(
        &config,
        r#"{"cargo":{"buildScripts":{"overrideCommand":["cargo","--version"]}},"procMacro":{"enable":false},"cfg":{"setTest":false}}"#,
    )
    .map_err(|e| e.to_string())?;
    let output = dir.path().join("index.scip");
    // Confined to the project and `dir` (ADR 0007), on the user's toolchain.
    let mut command = crate::compiler_sandbox::command(executable, root, dir.path());
    pin_toolchain(&mut command);
    command
        .arg("scip")
        .arg(root)
        .arg("--output")
        .arg(&output)
        .arg("--config-path")
        .arg(&config)
        .env("CARGO_NET_OFFLINE", "true")
        .env("CARGO_TARGET_DIR", dir.path().join("target"))
        .env("RUSTC_WRAPPER", "")
        .env("RUSTC_WORKSPACE_WRAPPER", "")
        .env("CARGO_BUILD_RUSTC_WRAPPER", "")
        .env("CARGO_BUILD_RUSTC_WORKSPACE_WRAPPER", "");
    crate::go_calls::execute(&mut command, dir.path(), None, "rust-analyzer scip", HINT)?;
    let bytes = std::fs::read(&output).map_err(|e| format!("rust-analyzer wrote no index: {e}"))?;
    Ok((version, bytes))
}

#[tracing::instrument(skip_all)]
fn parse(version: String, bytes: &[u8]) -> Result<ScipIndex, String> {
    let parsed = Index::parse_from_bytes(bytes).map_err(|e| format!("invalid SCIP index: {e}"))?;
    let mut index = ScipIndex {
        version,
        occurrences: HashMap::new(),
        definitions: HashMap::new(),
        encodings: HashMap::new(),
        pending: None,
    };
    for document in parsed.documents {
        let path = document.relative_path;
        let encoding = document
            .position_encoding
            .enum_value()
            .unwrap_or(PositionEncoding::UnspecifiedPositionEncoding);
        index.encodings.insert(path.clone(), encoding);
        for occurrence in document.occurrences {
            let [line, start, ..] = occurrence.range[..] else {
                continue;
            };
            let (Ok(line), Ok(start)) = (u32::try_from(line), u32::try_from(start)) else {
                continue;
            };
            if occurrence.symbol_roles & DEFINITION != 0 {
                index
                    .definitions
                    .entry(occurrence.symbol.clone())
                    .or_insert((path.clone(), line));
            }
            index
                .occurrences
                .entry(path.clone())
                .or_default()
                .entry((line, start))
                .or_insert(occurrence.symbol);
        }
    }
    Ok(index)
}

impl ScipIndex {
    /// `resolved` and, for an index of an earlier state, what is pending.
    pub(crate) fn notes(&self, resolved: &str) -> Vec<String> {
        let mut notes = vec![resolved.to_string()];
        if let Some(pending) = &self.pending {
            notes.push(format!(
                "rust-analyzer: calls in sources changed since the last index, and calls into them, stay unresolved; {pending}"
            ));
        }
        notes
    }
    /// The index without the occurrences and definitions in `documents`.
    fn without(mut self, documents: &HashSet<String>) -> Self {
        self.occurrences.retain(|doc, _| !documents.contains(doc));
        self.definitions
            .retain(|_, (doc, _)| !documents.contains(doc));
        self
    }
    /// The SCIP position of a 1-based line and 0-based character column in `text`,
    /// the source line itself.
    pub(crate) fn position(
        &self,
        rel_path: &str,
        text: &str,
        line: u32,
        column: u32,
    ) -> (u32, u32) {
        let encoding = self
            .encodings
            .get(rel_path)
            .copied()
            .unwrap_or(PositionEncoding::UnspecifiedPositionEncoding);
        (line.saturating_sub(1), offset(text, column, encoding))
    }
    /// The non-local symbol starting at a 1-based line and 0-based character column.
    pub(crate) fn symbol_at(
        &self,
        rel_path: &str,
        text: &str,
        line: u32,
        column: u32,
    ) -> Option<&String> {
        let position = self.position(rel_path, text, line, column);
        self.occurrences
            .get(rel_path)?
            .get(&position)
            .filter(|s| !s.starts_with("local "))
    }
    /// Non-local symbols of a document between two SCIP positions (end exclusive).
    pub(crate) fn symbols_between(
        &self,
        rel_path: &str,
        start: (u32, u32),
        end: (u32, u32),
    ) -> impl Iterator<Item = (u32, &String)> {
        self.occurrences
            .get(rel_path)
            .into_iter()
            .flat_map(move |document| document.range(start..end.max(start)))
            .filter(|(_, symbol)| !symbol.starts_with("local "))
            .map(|((line, _), symbol)| (*line, symbol))
    }
    /// The document and 0-based line of a symbol's definition inside the project.
    pub(crate) fn definition(&self, symbol: &str) -> Option<&(String, u32)> {
        self.definitions.get(symbol)
    }
}

/// The offset of a 0-based character column in a line under `encoding`.
fn offset(line: &str, column: u32, encoding: PositionEncoding) -> u32 {
    let prefix = line.chars().take(column as usize);
    match encoding {
        PositionEncoding::UTF16CodeUnitOffsetFromLineStart => {
            prefix.map(char::len_utf16).sum::<usize>() as u32
        }
        PositionEncoding::UTF32CodeUnitOffsetFromLineStart => column,
        // rust-analyzer writes UTF-8; an unspecified encoding is read the same way.
        _ => prefix.map(char::len_utf8).sum::<usize>() as u32,
    }
}

type ByFileAndName<'a, T> = HashMap<(&'a str, &'a str), T>;

/// Methods and classes by file and (last) name, in report order: the first
/// match wins, as a search through the report would find it.
fn declarations(
    report: &CallAnalysis,
) -> (
    ByFileAndName<'_, Vec<&CallMethod>>,
    ByFileAndName<'_, &CallClass>,
) {
    let mut methods: ByFileAndName<Vec<&CallMethod>> = HashMap::new();
    for m in &report.methods {
        methods.entry((&m.file, &m.name)).or_default().push(m);
    }
    let mut classes: ByFileAndName<&CallClass> = HashMap::new();
    for c in &report.classes {
        let name = c.name.rsplit("::").next().unwrap_or(&c.name);
        classes.entry((&c.file, name)).or_insert(c);
    }
    (methods, classes)
}

/// Resolve every call site against the index and the measured declarations.
#[tracing::instrument(skip_all)]
pub(crate) fn resolve(
    index: &ScipIndex,
    report: &CallAnalysis,
    sources: &[Source],
    sites: &[(String, String, CallSite)],
) -> Vec<MethodCall> {
    let by_stripped: HashMap<&str, (&Source, Vec<usize>)> = sources
        .iter()
        .map(|s| (s.stripped.as_str(), (s, line_starts(&s.text))))
        .collect();
    let stripped_of: HashMap<&str, &str> = sources
        .iter()
        .map(|s| (s.rel_path.as_str(), s.stripped.as_str()))
        .collect();
    let file_of: HashMap<&str, &str> = report
        .methods
        .iter()
        .map(|m| (m.id.as_str(), m.file.as_str()))
        .collect();
    let (methods, classes) = declarations(report);
    let mut calls = Vec::new();
    for (class_id, method_id, site) in sites {
        let Some((source, starts)) = file_of
            .get(method_id.as_str())
            .and_then(|f| by_stripped.get(f))
        else {
            continue;
        };
        let text = line_at(&source.text, starts, site.line);
        let symbol = index.symbol_at(&source.rel_path, text, site.line, site.column);
        let name = site.label.rsplit("::").next().unwrap_or(&site.label);
        let (resolution, to_class, to_method) = match symbol {
            None => ("unresolved", None, None),
            Some(symbol) => match index.definitions.get(symbol) {
                None => ("external", None, None),
                Some((path, line)) => {
                    let file = stripped_of.get(path.as_str()).copied().unwrap_or(path);
                    let target = methods.get(&(file, name)).and_then(|ms| {
                        ms.iter()
                            .find(|m| m.line <= line + 1 && *line < m.end_line.unwrap_or(m.line))
                    });
                    match target {
                        Some(m) => ("project", Some(m.class_id.clone()), Some(m.id.clone())),
                        None => {
                            let class = classes.get(&(file, name));
                            ("project", class.map(|c| c.id.clone()), None)
                        }
                    }
                }
            },
        };
        calls.push(MethodCall {
            from_class: class_id.clone(),
            from_method: Some(method_id.clone()),
            to_class,
            to_method,
            target_label: site.label.clone(),
            dispatch: if site.method_call {
                "instance"
            } else {
                "static"
            }
            .into(),
            resolution: resolution.into(),
            file: source.stripped.clone(),
            line: site.line,
            column: site.column + 1,
            code: text.trim().chars().take(200).collect(),
        });
    }
    calls
}

#[cfg(all(test, any(target_os = "macos", target_os = "linux")))]
mod tests {
    use super::*;

    #[test]
    fn the_version_probe_runs_confined_in_the_scratch_directory() {
        assert!(crate::compiler_sandbox::available());
        let (project, scratch, secret, tool) = (
            tempfile::tempdir().unwrap(),
            tempfile::tempdir().unwrap(),
            tempfile::tempdir().unwrap(),
            tempfile::tempdir().unwrap(),
        );
        let file = secret.path().join("s.txt");
        std::fs::write(&file, "secret").unwrap();
        // A stand-in for rust-analyzer in its own installation (`…/bin/ra`).
        std::fs::create_dir(tool.path().join("bin")).unwrap();
        let fake = tool.path().join("bin").join("ra");
        std::fs::write(
            &fake,
            format!("#!/bin/sh\ncat '{}' 2>/dev/null; pwd -P\n", file.display()),
        )
        .unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&fake, std::fs::Permissions::from_mode(0o755)).unwrap();
        let out = version(project.path(), fake.as_os_str(), scratch.path()).unwrap();
        assert!(!out.contains("secret"), "{out}");
        let cwd = scratch.path().canonicalize().unwrap();
        assert_eq!(out, cwd.to_string_lossy());
    }
}

#[cfg(test)]
mod resolve_tests {
    use super::*;

    fn method(id: &str, class: &str, name: &str, line: u32, end: u32) -> serde_json::Value {
        serde_json::json!({"id": id, "class_id": class, "name": name, "signature": "",
            "file": "a.rs", "line": line, "end_line": end, "is_static": false})
    }

    fn class(id: &str, name: &str) -> serde_json::Value {
        serde_json::json!({"id": id, "name": name, "package": "", "file": "a.rs",
            "graph_node": "a.rs", "line": 1, "kind": "struct"})
    }

    #[test]
    fn lines_split_as_str_lines_does() {
        for text in [
            "",
            "a",
            "a\n",
            "a\nb",
            "a\r\nb\r\n",
            "x\r",
            "a\rb\nc",
            "\n\n",
            "ä\nö\n",
        ] {
            let starts = line_starts(text);
            for line in 1..=5u32 {
                let expected = text.lines().nth(line as usize - 1).unwrap_or("");
                assert_eq!(
                    line_at(text, &starts, line),
                    expected,
                    "{text:?} line {line}"
                );
            }
            assert_eq!(line_at(text, &starts, 0), "", "line 0 of {text:?}");
        }
    }

    #[test]
    fn changed_documents_are_edited_gone_or_new() {
        let docs = |list: &[(&str, u8)]| -> HashMap<String, [u8; 32]> {
            list.iter()
                .map(|(p, h)| (p.to_string(), [*h; 32]))
                .collect()
        };
        let kept = docs(&[("same.rs", 1), ("edited.rs", 2), ("gone.rs", 3)]);
        let current = docs(&[("same.rs", 1), ("edited.rs", 9), ("new.rs", 4)]);
        let mut found: Vec<String> = changed(&kept, &current).into_iter().collect();
        found.sort();
        assert_eq!(found, ["edited.rs", "gone.rs", "new.rs"]);
    }

    #[test]
    fn an_earlier_index_keeps_only_unchanged_documents() {
        let index = ScipIndex {
            version: String::new(),
            occurrences: HashMap::from([
                (
                    "a.rs".to_string(),
                    BTreeMap::from([((0, 0), "s a".to_string())]),
                ),
                (
                    "b.rs".to_string(),
                    BTreeMap::from([((0, 0), "s b".to_string())]),
                ),
            ]),
            definitions: HashMap::from([
                ("s a".to_string(), ("a.rs".to_string(), 0)),
                ("s b".to_string(), ("b.rs".to_string(), 0)),
            ]),
            encodings: HashMap::new(),
            pending: None,
        };
        let pruned = index.without(&HashSet::from(["b.rs".to_string()]));
        assert!(pruned.occurrences.contains_key("a.rs"));
        assert!(
            !pruned.occurrences.contains_key("b.rs"),
            "changed: positions moved"
        );
        assert!(pruned.definition("s a").is_some());
        assert!(
            pruned.definition("s b").is_none(),
            "its lines may have moved"
        );
    }

    #[test]
    fn call_sites_resolve_to_the_first_matching_declaration() {
        let report: CallAnalysis = serde_json::from_value(serde_json::json!({
            "status": "partial", "files": 1, "calls": [], "diagnostics": [],
            "classes": [class("X", "m::Thing"), class("Y", "Thing"), class("Z", "Other")],
            "methods": [
                method("main", "Z", "main", 1, 5),
                method("A::run", "A", "run", 6, 8),
                method("B::run", "B", "run", 10, 12),
                method("C::run", "C", "run", 10, 12),
            ],
        }))
        .unwrap();
        let text = "fn main() {\n    run(); Thing(1); ext(); none();\n}\n".to_string();
        let sources = [Source {
            rel_path: "a.rs".into(),
            stripped: "a.rs".into(),
            text,
        }];
        let at = |column: u32, symbol: &str| ((1, column), symbol.to_string());
        let index = ScipIndex {
            version: String::new(),
            occurrences: HashMap::from([(
                "a.rs".to_string(),
                BTreeMap::from([at(4, "s run"), at(11, "s Thing"), at(21, "s ext")]),
            )]),
            definitions: HashMap::from([
                ("s run".to_string(), ("a.rs".to_string(), 10)),
                ("s Thing".to_string(), ("a.rs".to_string(), 0)),
            ]),
            encodings: HashMap::new(),
            pending: None,
        };
        let site = |column: u32, label: &str| {
            let site = CallSite {
                line: 2,
                column,
                label: label.into(),
                method_call: false,
            };
            ("Z".to_string(), "main".to_string(), site)
        };
        let sites = [
            site(4, "run"),
            site(11, "Thing"),
            site(21, "ext"),
            site(28, "none"),
        ];
        let got: Vec<_> = resolve(&index, &report, &sources, &sites)
            .into_iter()
            .map(|c| (c.resolution, c.to_class, c.to_method))
            .collect();
        let s = |v: &str| Some(v.to_string());
        assert_eq!(
            got,
            [
                ("project".into(), s("B"), s("B::run")),
                ("project".into(), s("X"), None),
                ("external".into(), None, None),
                ("unresolved".into(), None, None),
            ]
        );
    }
}
